<?php
declare(strict_types=1);
use ConectaFlow\{Auth, Config, Database, Security};
use function ConectaFlow\{db, flash, takeFlashes, redirect, userCompanyId};
session_set_cookie_params(['httponly'=>true, 'samesite'=>'Lax', 'secure'=>!empty($_SERVER['HTTPS'])]);
session_start();
require_once __DIR__.'/../src/Config.php'; require_once __DIR__.'/../src/Database.php'; require_once __DIR__.'/../src/Security.php'; require_once __DIR__.'/../src/Auth.php'; require_once __DIR__.'/../src/MetaClient.php'; require_once __DIR__.'/../src/Support.php';
Config::load(__DIR__.'/../.env');

$page = $_GET['page'] ?? 'dashboard'; $user = Auth::user();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        Security::validateCsrf($_POST['_csrf'] ?? null); $action = $_POST['action'] ?? '';
        if ($action === 'login') { if (Auth::login(trim($_POST['email'] ?? ''), $_POST['password'] ?? '')) redirect('?page=dashboard'); flash('error','E-mail ou senha inválidos.'); redirect('?page=login'); }
        $user = Auth::requireLogin(); $companyId = userCompanyId($user);
        if ($action === 'logout') { Auth::logout(); redirect('?page=login'); }
        if ($action === 'create_contact') {
            $name=trim($_POST['name']??''); $phone=preg_replace('/[^0-9+]/','',$_POST['phone']??'');
            if ($name === '' || strlen($phone)<8) throw new RuntimeException('Informe nome e telefone válidos.');
            db()->prepare('INSERT INTO contacts (company_id,name,phone,email,contact_company,source) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name), email=VALUES(email), updated_at=NOW()')->execute([$companyId,$name,$phone,trim($_POST['email']??'') ?: null,trim($_POST['contact_company']??'') ?: null,trim($_POST['source']??'') ?: null]);
            flash('success','Contato salvo no CRM.'); redirect('?page=contacts');
        }
        if ($action === 'import_contacts') {
            if (empty($_FILES['contacts_file']['tmp_name']) || $_FILES['contacts_file']['error'] !== UPLOAD_ERR_OK) throw new RuntimeException('Selecione um arquivo CSV ou Excel válido.');
            $file=$_FILES['contacts_file']; $ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION)); $rows=[];
            if ($ext==='csv') { $handle=fopen($file['tmp_name'],'rb'); while(($row=fgetcsv($handle,0,','))!==false) $rows[]=$row; fclose($handle); }
            elseif (in_array($ext,['xlsx','xls'],true)) { $autoload=__DIR__.'/../vendor/autoload.php'; if(!is_file($autoload)) throw new RuntimeException('Execute composer install para habilitar a importação Excel.'); require_once $autoload; $sheet=\PhpOffice\PhpSpreadsheet\IOFactory::load($file['tmp_name'])->getActiveSheet(); $rows=$sheet->toArray(); }
            else throw new RuntimeException('Formato não suportado. Use CSV, XLS ou XLSX.');
            if(count($rows)<2) throw new RuntimeException('A planilha precisa ter cabeçalho e pelo menos um contato.'); $headers=array_map(fn($v)=>strtolower(trim((string)$v)),array_shift($rows)); $map=[]; foreach(['nome','name','telefone','phone','email','empresa','company','origem','source'] as $key){$idx=array_search($key,$headers,true);if($idx!==false)$map[$key]=$idx;}
            if (!isset($map['nome'])&&!isset($map['name'])) throw new RuntimeException('A coluna nome é obrigatória.'); if(!isset($map['telefone'])&&!isset($map['phone'])) throw new RuntimeException('A coluna telefone é obrigatória.');
            $stmt=db()->prepare('INSERT INTO contacts(company_id,name,phone,email,contact_company,source) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),email=VALUES(email),contact_company=VALUES(contact_company),source=VALUES(source),updated_at=NOW()');$imported=0;
            foreach($rows as $row){$name=trim((string)($row[$map['nome']??$map['name']]??''));$phone=preg_replace('/[^0-9+]/','',(string)($row[$map['telefone']??$map['phone']]??''));if(!$name||strlen($phone)<8)continue;$email=isset($map['email'])?trim((string)($row[$map['email']]??'')):null;$company=isset($map['empresa'])?trim((string)($row[$map['empresa']]??'')):null;$source=isset($map['origem'])?trim((string)($row[$map['origem']]??'')):'importacao';$stmt->execute([$companyId,$name,$phone,$email?:null,$company?:null,$source?:null]);$imported++;}
            flash('success',"$imported contatos importados/atualizados com sucesso."); redirect('?page=contacts');
        }
        if ($action === 'toggle_optout') {
            $contactId=(int)$_POST['contact_id']; $stmt=db()->prepare('SELECT phone,opted_out_at FROM contacts WHERE id=? AND company_id=?'); $stmt->execute([$contactId,$companyId]); $c=$stmt->fetch(); if(!$c) throw new RuntimeException('Contato não encontrado.');
            if ($c['opted_out_at']) { db()->prepare('UPDATE contacts SET opted_out_at=NULL,status="active" WHERE id=? AND company_id=?')->execute([$contactId,$companyId]); db()->prepare('DELETE FROM suppression_list WHERE company_id=? AND phone=?')->execute([$companyId,$c['phone']]); flash('success','Contato reativado.'); }
            else { db()->prepare('UPDATE contacts SET opted_out_at=NOW(),status="inactive" WHERE id=? AND company_id=?')->execute([$contactId,$companyId]); db()->prepare('INSERT IGNORE INTO suppression_list(company_id,phone,reason) VALUES(?,?,?)')->execute([$companyId,$c['phone'],'opt_out']); flash('success','Contato incluído na supressão.'); }
            redirect('?page=contacts');
        }
        if ($action === 'create_campaign') {
            $name=trim($_POST['name']??''); $text=trim($_POST['message_text']??''); if(!$name || !$text) throw new RuntimeException('Nome e mensagem são obrigatórios.');
            $filter=['status'=>'active','tag'=>trim($_POST['tag']??'')]; $scheduled=!empty($_POST['scheduled_at']) ? date('Y-m-d H:i:s',strtotime($_POST['scheduled_at'])) : null;
            db()->prepare('INSERT INTO campaigns(company_id,created_by,name,category,message_text,audience_filter_json,status,scheduled_at) VALUES(?,?,?,?,?,?,?,?)')->execute([$companyId,$user['id'],$name,$_POST['category']??'marketing',$text,json_encode($filter),'draft',$scheduled]); flash('success','Campanha criada como rascunho. Revise e enfileire após validar o público.'); redirect('?page=campaigns');
        }
        if ($action === 'launch_campaign') {
            $campaignId=(int)$_POST['campaign_id']; Database::transaction(function($pdo) use($campaignId,$companyId) {
                $q=$pdo->prepare('SELECT * FROM campaigns WHERE id=? AND company_id=? FOR UPDATE'); $q->execute([$campaignId,$companyId]); $c=$q->fetch(); if(!$c) throw new RuntimeException('Campanha não encontrada.');
                $contacts=$pdo->prepare('SELECT id FROM contacts WHERE company_id=? AND status="active" AND opted_out_at IS NULL AND id NOT IN (SELECT contact_id FROM campaign_contacts WHERE campaign_id=?)'); $contacts->execute([$companyId,$campaignId]); $ins=$pdo->prepare('INSERT INTO campaign_contacts(campaign_id,contact_id,status) VALUES(?,?,"pending")'); foreach($contacts as $row)$ins->execute([$campaignId,$row['id']]);
                $pdo->prepare('UPDATE campaigns SET status=IF(scheduled_at IS NULL,"processing","scheduled"), total_count=(SELECT COUNT(*) FROM campaign_contacts WHERE campaign_id=?) WHERE id=? AND company_id=?')->execute([$campaignId,$campaignId,$companyId]);
            }); flash('success','Campanha confirmada e protegida por fila.'); redirect('?page=campaigns');
        }
        if ($action === 'pause_campaign') { db()->prepare('UPDATE campaigns SET status="paused" WHERE id=? AND company_id=? AND status IN ("scheduled","processing")')->execute([(int)$_POST['campaign_id'],$companyId]); flash('success','Campanha pausada.'); redirect('?page=campaigns'); }
        if ($action === 'connect_whatsapp') {
            $waba=trim($_POST['waba_id']??''); $phoneId=trim($_POST['phone_number_id']??''); $token=trim($_POST['access_token']??'');
            if (!$waba || !$phoneId || !$token) throw new RuntimeException('WABA ID, Phone Number ID e token são obrigatórios.');
            Database::transaction(function($pdo)use($companyId,$waba,$phoneId,$token){
                $pdo->prepare('INSERT INTO whatsapp_accounts(company_id,waba_id,access_token_encrypted,status) VALUES(?,?,?,"connected") ON DUPLICATE KEY UPDATE access_token_encrypted=VALUES(access_token_encrypted),status="connected",updated_at=NOW()')->execute([$companyId,$waba,Security::encrypt($token)]);
                $q=$pdo->prepare('SELECT id FROM whatsapp_accounts WHERE company_id=? AND waba_id=?');$q->execute([$companyId,$waba]);$accountId=$q->fetchColumn();
                $pdo->prepare('INSERT INTO whatsapp_numbers(whatsapp_account_id,phone_number_id,display_phone_number,verified_name,status) VALUES(?,?,?,?,"connected") ON DUPLICATE KEY UPDATE display_phone_number=VALUES(display_phone_number),status="connected"')->execute([$accountId,$phoneId,trim($_POST['display_phone_number']??'')?:null,trim($_POST['verified_name']??'')?:null]);
            }); flash('success','Conta oficial conectada com segurança. Faça uma sincronização para consultar templates e limite atual.'); redirect('?page=settings');
        }
    } catch (Throwable $e) { flash('error',$e->getMessage()); redirect('?page='.urlencode($page)); }
}

function countValue(string $sql, array $params): int { try { $s=db()->prepare($sql); $s->execute($params); return (int)$s->fetchColumn(); } catch(Throwable) { return 0; } }
function companyRow(int $id): array { $s=db()->prepare('SELECT * FROM companies WHERE id=?'); $s->execute([$id]); return $s->fetch() ?: []; }
