if ($page === 'contacts') { renderHeader('Contatos',$user); $filter=$_GET['q']??''; $stmt=db()->prepare('SELECT c.*, GROUP_CONCAT(t.name SEPARATOR ", ") tags FROM contacts c LEFT JOIN contact_tags ct ON ct.contact_id=c.id LEFT JOIN tags t ON t.id=ct.tag_id WHERE c.company_id=? AND (c.name LIKE ? OR c.phone LIKE ? OR c.email LIKE ?) GROUP BY c.id ORDER BY c.created_at DESC LIMIT 100');$like='%'.$filter.'%';$stmt->execute([$companyId,$like,$like,$like]);$rows=$stmt->fetchAll(); ?><div class="page-actions"><div><p class="muted">CRM / BASE DE CONTATOS</p><h2>Todos os contatos <span class="count-pill"><?=count($rows)?></span></h2></div><div class="actions"><button class="secondary" onclick="document.getElementById('import-modal').showModal()">↑ Importar</button><button class="primary" onclick="document.getElementById('contact-modal').showModal()">＋ Novo contato</button></div></div><div class="filter-bar"><form><input type="hidden" name="page" value="contacts"><span>⌕</span><input name="q" value="<?=Security::e($filter)?>" placeholder="Buscar por nome, telefone ou e-mail..."></form><button>⚙ Filtros</button><span class="muted"><?=number_format(count($rows),0,',','.')?> resultados</span></div><div class="panel table-panel full"><table><thead><tr><th class="check-col"><input type="checkbox"></th><th>CONTATO</th><th>TELEFONE</th><th>TAGS</th><th>ORIGEM</th><th>STATUS</th><th>ÚLTIMA INTERAÇÃO</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="empty">Nenhum contato encontrado. Cadastre ou importe sua primeira lista.</td></tr><?php else: foreach($rows as $r): ?><tr><td><input type="checkbox"></td><td><div class="contact-cell"><span class="contact-avatar"><?=strtoupper(substr($r['name'],0,1))?></span><b><?=Security::e($r['name'])?></b></div></td><td><?=Security::e($r['phone'])?></td><td><?php foreach(array_filter(explode(', ',$r['tags']??'')) as $tag):?><span class="tag"><?=Security::e($tag)?></span><?php endforeach;?></td><td><?=Security::e($r['source']??'—')?></td><td><span class="status-dot <?= $r['opted_out_at']?'off':''?>">● <?= $r['opted_out_at']?'suprimido':'ativo'?></span></td><td><?= $r['last_interaction_at']?date('d/m/Y H:i',strtotime($r['last_interaction_at'])):'—'?></td><td><form method="post" onsubmit="return confirm('Alterar status de consentimento deste contato?')"><input type="hidden" name="_csrf" value="<?=Security::csrf()?>"><input type="hidden" name="contact_id" value="<?=$r['id']?>"><button class="more" name="action" value="toggle_optout">···</button></form></td></tr><?php endforeach; endif;?></tbody></table></div><dialog id="contact-modal"><form method="post" class="modal-form"><button type="button" class="modal-close" onclick="this.closest('dialog').close()">×</button><span class="eyebrow">CRM</span><h2>Novo contato</h2><input type="hidden" name="_csrf" value="<?=Security::csrf()?>"><input type="hidden" name="action" value="create_contact"><label>Nome completo<input name="name" required></label><label>WhatsApp<input name="phone" placeholder="5511999999999" required></label><label>E-mail<input name="email" type="email"></label><label>Empresa<input name="contact_company"></label><label>Origem<select name="source"><option>Importação manual</option><option>Landing page</option><option>Indicação</option><option>Evento</option></select></label><button class="primary wide">Salvar contato</button></form></dialog><dialog id="import-modal"><div class="modal-form"><button class="modal-close" onclick="this.closest('dialog').close()">×</button><span class="eyebrow">IMPORTAÇÃO</span><h2>Importar contatos</h2><p class="muted">A estrutura de importação aceita CSV UTF-8 com as colunas: nome, telefone, email, empresa, origem. O processamento completo pode ser conectado ao worker de importação.</p><div class="dropzone">＋<b>Solte seu arquivo CSV aqui</b><small>ou clique para selecionar · até 10 MB</small></div><button class="secondary wide" onclick="this.closest('dialog').close()">Fechar</button></div></dialog><?php renderFooter(); exit; }

if ($page === 'campaigns') { renderHeader('Campanhas',$user); $rows=db()->prepare('SELECT c.*,u.name creator FROM campaigns c JOIN users u ON u.id=c.created_by WHERE c.company_id=? ORDER BY c.created_at DESC');$rows->execute([$companyId]);$campaigns=$rows->fetchAll(); $new=isset($_GET['new']); ?><div class="page-actions"><div><p class="muted">ENGAJAMENTO / ENVIO RESPONSÁVEL</p><h2>Campanhas</h2></div><button class="primary" onclick="document.getElementById('campaign-modal').showModal()">＋ Criar campanha</button></div><div class="campaign-cards"><div class="summary-card"><small>Este mês</small><b><?=count($campaigns)?></b><span>campanhas criadas</span></div><div class="summary-card"><small>Em processamento</small><b><?=count(array_filter($campaigns,fn($r)=>$r['status']==='processing'))?></b><span>protegidas pela fila</span></div><div class="summary-card"><small>Custo estimado</small><b>R$ 0,00</b><span>tarifas Meta separadas</span></div></div><div class="panel table-panel full"><div class="panel-head"><div><h3>Histórico de campanhas</h3><p>Revise o público e o status antes de cada disparo.</p></div><div class="segmented"><button class="selected">Todas</button><button>Ativas</button><button>Concluídas</button></div></div><table><thead><tr><th>CAMPANHA</th><th>PÚBLICO</th><th>STATUS</th><th>PROGRESSO</th><th>RESULTADO</th><th></th></tr></thead><tbody><?php if(!$campaigns):?><tr><td colspan="6" class="empty">Crie sua primeira campanha para começar.</td></tr><?php else: foreach($campaigns as $r): $pct=$r['total_count']?min(100,round(($r['sent_count']/$r['total_count'])*100)):0; ?><tr><td><b><?=Security::e($r['name'])?></b><small><?=date('d/m/Y H:i',strtotime($r['created_at']))?> · <?=Security::e($r['creator'])?></small></td><td><?=number_format((int)$r['total_count'],0,',','.')?> contatos</td><td><span class="badge <?=Security::e($r['status'])?>"><?=['draft'=>'Rascunho','scheduled'=>'Agendada','processing'=>'Em processamento','completed'=>'Concluída','paused'=>'Pausada','canceled'=>'Cancelada'][$r['status']]??$r['status']?></span></td><td><div class="mini-progress"><span style="width:<?=$pct?>%"></span></div><small><?=$pct?>% · <?=$r['sent_count']?> enviados</small></td><td><b><?=$r['delivered_count']?></b> entregues <small>/ <?=$r['failed_count']?> falhas</small></td><td><?php if(in_array($r['status'],['draft','paused'])):?><form method="post"><input type="hidden" name="_csrf" value="<?=Security::csrf()?>"><input type="hidden" name="campaign_id" value="<?=$r['id']?>"><button class="small-action" name="action" value="launch_campaign">▶ Iniciar</button></form><?php elseif($r['status']==='processing'):?><form method="post"><input type="hidden" name="_csrf" value="<?=Security::csrf()?>"><input type="hidden" name="campaign_id" value="<?=$r['id']?>"><button class="more" name="action" value="pause_campaign">Ⅱ</button></form><?php endif;?></td></tr><?php endforeach; endif;?></tbody></table></div><dialog id="campaign-modal" <?= $new?'open':'' ?>><form method="post" class="modal-form wide-modal"><button type="button" class="modal-close" onclick="this.closest('dialog').close()">×</button><span class="eyebrow">NOVA CAMPANHA</span><h2>Crie uma comunicação com propósito</h2><p class="muted">A fila só envia para contatos ativos, consentidos e fora da lista de supressão.</p><input type="hidden" name="_csrf" value="<?=Security::csrf()?>"><input type="hidden" name="action" value="create_campaign"><label>Nome interno<input name="name" placeholder="Ex.: Lançamento coleção verão" required></label><div class="two-col"><label>Categoria<select name="category"><option value="marketing">Marketing</option><option value="utility">Utilidade</option><option value="authentication">Autenticação</option></select></label><label>Agendar (opcional)<input type="datetime-local" name="scheduled_at"></label></div><label>Mensagem<textarea name="message_text" rows="5" placeholder="Olá, {{nome}}! Temos uma novidade para você..." required></textarea><div class="variable-hint">Variáveis disponíveis: <code>{{nome}}</code> <code>{{empresa}}</code> <code>{{telefone}}</code></div><label>Tag do público (opcional)<input name="tag" placeholder="Ex.: clientes-vip"></label><div class="preview-box"><span>PRÉVIA DA MENSAGEM</span><p>Olá, <b>Marina</b>! Temos uma novidade para você.</p><small>O conteúdo final será validado conforme template aprovado na Meta.</small></div><button class="primary wide">Salvar rascunho e revisar →</button></form></dialog><?php renderFooter(); exit; }

if ($page === 'inbox') { renderHeader('Caixa de entrada',$user); $s=db()->prepare('SELECT cv.*,c.name,c.phone FROM conversations cv JOIN contacts c ON c.id=cv.contact_id WHERE cv.company_id=? ORDER BY COALESCE(cv.last_message_at,cv.updated_at) DESC LIMIT 50');$s->execute([$companyId]);$convs=$s->fetchAll(); ?><div class="page-actions"><div><p class="muted">ATENDIMENTO OMNICHANNEL</p><h2>Caixa de entrada</h2></div><div class="inbox-filters"><button class="selected">Todos <b><?=count($convs)?></b></button><button>Não lidos</button><button>Atribuídos a mim</button></div></div><div class="inbox-layout"><div class="panel conversation-list"><div class="inbox-search">⌕ <input placeholder="Buscar conversa..."></div><?php if(!$convs):?><div class="empty">Nenhuma conversa recebida ainda.</div><?php else: foreach($convs as $i=>$c):?><div class="conversation <?= $i===0?'selected':''?>"><span class="contact-avatar <?= $i%3===1?'purple':($i%3===2?'orange':'')?>"><?=strtoupper(substr($c['name'],0,1))?></span><div><b><?=Security::e($c['name'])?></b><small><?=Security::e($c['phone'])?></small><p><?=Security::e($c['status'])?> · <?= $c['last_message_at']?date('H:i',strtotime($c['last_message_at'])):'sem mensagens'?></p></div><i class="unread"></i></div><?php endforeach; endif;?></div><div class="panel chat-panel"><div class="chat-empty"><span class="chat-icon">▱</span><h3>Selecione uma conversa</h3><p>As mensagens e o histórico do contato aparecerão aqui.</p></div></div><div class="panel contact-detail"><div class="detail-top"><span class="contact-avatar large">M</span><h3>Detalhes do contato</h3><button>···</button></div><div class="detail-card"><small>CONTATO</small><b>Selecione uma conversa</b></div><div class="detail-card"><small>JANELA DE ATENDIMENTO</small><span class="status-dot">● Disponível</span><p>Respostas livres permitidas dentro da janela oficial.</p></div></div></div><?php renderFooter(); exit; }

if ($page === 'settings') { renderHeader('Conexões WhatsApp',$user); $s=db()->prepare('SELECT wa.*,wn.phone_number_id,wn.display_phone_number,wn.verified_name FROM whatsapp_accounts wa LEFT JOIN whatsapp_numbers wn ON wn.whatsapp_account_id=wa.id WHERE wa.company_id=? ORDER BY wa.id DESC LIMIT 1');$s->execute([$companyId]);$wa=$s->fetch(); ?><div class="page-actions"><div><p class="muted">META CLOUD API / CREDENCIAIS DA EMPRESA</p><h2>Conexões WhatsApp</h2></div><?php if($wa):?><span class="pill green">● CONECTADO</span><?php endif;?></div><div class="placeholder-grid"><div class="panel"><div class="panel-head"><div><h3>Conta oficial da Meta</h3><p>Uma credencial isolada para este workspace.</p></div><span class="live">OFICIAL</span></div><form method="post" class="settings-form"><input type="hidden" name="_csrf" value="<?=Security::csrf()?>"><input type="hidden" name="action" value="connect_whatsapp"><label>WABA ID<input name="waba_id" value="<?=Security::e($wa['waba_id']??'')?>" placeholder="123456789012345"></label><label>Phone Number ID<input name="phone_number_id" value="<?=Security::e($wa['phone_number_id']??'')?>" placeholder="106540352242922"></label><div class="two-col"><label>Telefone exibido<input name="display_phone_number" value="<?=Security::e($wa['display_phone_number']??'')?>" placeholder="+55 11 99999-9999"></label><label>Nome verificado<input name="verified_name" value="<?=Security::e($wa['verified_name']??'')?>" placeholder="Empresa Demo"></label></div><label>Token de acesso permanente<input type="password" name="access_token" placeholder="<?= $wa?'Token já salvo · informe apenas para substituir':'Cole o token gerado no Business Manager'?>"></label><div class="security-note">🔒 O token é criptografado antes de ser persistido e nunca é exibido novamente.</div><button class="primary">Salvar conexão e validar →</button></form></div><div class="panel checklist"><h3>Status da integração</h3><div><i><?= $wa?'✓':'1'?></i><span>Conta Meta<small><?= $wa?'WABA '.$wa['waba_id']:'Aguardando configuração'?></small></span></div><div><i><?= $wa?'✓':'2'?></i><span>Webhook<small>URL: /webhook.php · verificação por token</small></span></div><div><i>3</i><span>Templates aprovados<small>Sincronize após conectar</small></span></div><div><i>4</i><span>Limites e qualidade<small>Atualizados pela API oficial</small></span></div></div></div><?php renderFooter(); exit; }

